function createGame(mode){
 const capitalPairs=[['مصر','Egypt','القاهرة','Cairo'],['السعودية','Saudi Arabia','الرياض','Riyadh'],['فرنسا','France','باريس','Paris'],['اليابان','Japan','طوكيو','Tokyo'],['البرازيل','Brazil','برازيليا','Brasília'],['كندا','Canada','أوتاوا','Ottawa'],['أستراليا','Australia','كانبرا','Canberra'],['إسبانيا','Spain','مدريد','Madrid'],['الهند','India','نيودلهي','New Delhi'],['الصين','China','بكين','Beijing'],['الأرجنتين','Argentina','بوينس آيرس','Buenos Aires']];
 const shuffled=arr=>arr.slice().sort(()=>Math.random()-.5);
 const ids=['oceans','deserts','rivers','waterfalls','forests','mountains','lakes','islands','volcanoes','seas'];
 const q=[];
 if(mode==='mixed')return shuffled(baseQuiz);
 if(mode==='flags')for(const target of shuffled(flagCountries).slice(0,12)){const choices=shuffled([target,...shuffled(flagCountries.filter(x=>x!==target)).slice(0,3)]);q.push(['لأي دولة ينتمي هذا العلم؟ '+target[0],'Which country has this flag? '+target[0],choices.map(x=>x[1]),choices.map(x=>x[2]),choices.indexOf(target),'العلم يخص '+target[1],'This flag belongs to '+target[2]]);}
 if(mode==='mapfind')return shuffled(flagCountries.filter(x=>['Egypt','France','Japan','Brazil','Canada','Australia','Spain','India','China','Argentina','Germany','Italy'].includes(x[2]))).slice(0,9).map(x=>['اضغط على '+x[1]+' على الخريطة','Click '+x[2]+' on the map',[],[],0,'الدولة الصحيحة: '+x[1],'Correct country: '+x[2],x[2]]);

 if(mode==='capitals')for(const x of shuffled(capitalPairs)){const choices=shuffled([x,...shuffled(capitalPairs.filter(y=>y!==x)).slice(0,3)]);q.push(['ما عاصمة '+x[0]+'؟','What is the capital of '+x[1]+'?',choices.map(y=>y[2]),choices.map(y=>y[3]),choices.indexOf(x),'العاصمة الصحيحة: '+x[2],'Correct capital: '+x[3]]);}
 if(mode==='classify')for(const id of shuffled(ids)){const cat=cats.find(c=>c.id===id);for(const place of shuffled((geo[id]||[]).slice(0,2))){const opts=shuffled([id,...shuffled(ids.filter(x=>x!==id)).slice(0,3)]);q.push(['إلى أي قسم ينتمي '+place[0]+'؟','Which category includes '+place[1]+'?',opts.map(x=>cats.find(c=>c.id===x).ar),opts.map(x=>cats.find(c=>c.id===x).en),opts.indexOf(id),place[0]+' من '+cat.ar,place[1]+' belongs to '+cat.en]);}}
 if(mode==='definitions')for(const c of shuffled(cats)){const opts=shuffled([c,...shuffled(cats.filter(x=>x!==c)).slice(0,3)]);q.push(['أي مصطلح يطابق التعريف: '+topicDefinitions[c.id][0],'Which term matches: '+topicDefinitions[c.id][1],opts.map(x=>x.ar),opts.map(x=>x.en),opts.indexOf(c),c.ar+' — '+topicDefinitions[c.id][0],c.en+' — '+topicDefinitions[c.id][1]]);}
 if(mode==='locations')for(const id of ['continents','oceans','seas','deserts','rivers','mountains','waterfalls']){const sample=shuffled(geo[id]||[]).slice(0,3);for(const place of sample){const others=shuffled((geo[id]||[]).filter(x=>x!==place)).slice(0,3);const opts=shuffled([place,...others]);q.push(['أي موقع يرتبط بهذا الوصف: '+place[2],'Which place fits this description: '+place[3],opts.map(x=>x[0]),opts.map(x=>x[1]),opts.indexOf(place),place[0]+' — '+place[2],place[1]+' — '+place[3]]);}}
 return shuffled(q).slice(0,12);
}
