function searchResults(term){const matches=[];const t=term.trim().toLowerCase();if(t){for(const c of cats){if(`${c.ar} ${c.en}`.toLowerCase().includes(t))matches.push({title:`${c.emoji} ${label(c)}`,meta:lang('قسم','Category'),cat:c.id});(geo[c.id]||[]).forEach((v,i)=>{if(`${v[0]} ${v[1]} ${v[2]} ${v[3]}`.toLowerCase().includes(t))matches.push({title:lang(v[0],v[1]),meta:label(c),cat:c.id,item:i})})}}document.getElementById('searchResults').innerHTML=matches.slice(0,30).map(x=>`<button class="search-row" data-search-cat="${x.cat}" ${x.item!==undefined?`data-search-item="${x.item}"`:''}><strong>${escapeHTML(x.title)}</strong> <small>· ${escapeHTML(x.meta)}</small></button>`).join('')||`<div class="empty">${t?lang('لا توجد نتائج في البيانات الحالية','No results in current sample data'):lang('اكتب للبحث في الأقسام والأماكن','Type to search topics and places')}</div>`}
function openSearch(){document.getElementById('searchOverlay').classList.remove('hidden');document.getElementById('globalSearch').value='';searchResults('');document.getElementById('globalSearch').focus()}
function closeSearch(){document.getElementById('searchOverlay').classList.add('hidden')}
document.addEventListener('click',e=>{
 const borderToggle=e.target.closest('[data-map-boundaries]');if(borderToggle){const stage=atlasRuntime?.node.querySelector('.atlas-stage');if(stage){stage.classList.toggle('no-borders');borderToggle.classList.toggle('active');borderToggle.textContent=stage.classList.contains('no-borders')?lang('إظهار الحدود','Show borders'):lang('إخفاء الحدود','Hide borders')}return;}const zoom=e.target.closest('[data-map-zoom]');if(zoom){atlasZoom(zoom.dataset.mapZoom);return;}
 const pin=e.target.closest('[data-map-pin]');if(pin){const [id,i]=pin.dataset.mapPin.split(':');const v=geo[id][Number(i)];const pop=atlasRuntime?.node.querySelector('.atlas-popup');if(!pop)return;pop.innerHTML='<strong>'+escapeHTML(lang(v[0],v[1]))+'</strong><p>'+escapeHTML(lang(v[2],v[3]))+'</p><button data-atlas-open="'+id+':'+i+'">'+lang('عرض التفاصيل','See details')+' ←</button>';pop.classList.remove('hidden');return;}
 const open=e.target.closest('[data-atlas-open]');if(open){const [id,i]=open.dataset.atlasOpen.split(':');setPage('detail',id,Number(i));return;}
 const country=e.target.closest('[data-map-country]');if(country){const i=Number(country.dataset.mapCountry),f=atlasRuntime?.features[i];if(!f)return;if(state.page==='play'&&selectedGameMode==='mapfind'&&state.quizSelected===null){const expected=quiz[state.quizIndex][7],mapped={'United States of America':'United States','United Republic of Tanzania':'Tanzania','Czech Republic':'Czechia','Ivory Coast':'Côte d’Ivoire','Republic of the Congo':'Congo','Democratic Republic of the Congo':'DR Congo'},got=mapped[f.properties.name]||f.properties.name,matched=got.toLowerCase()===expected.toLowerCase();state.quizSelected=matched?0:1;if(matched)state.quizScore++;render();return;}atlasRuntime.node.querySelectorAll('.atlas-country').forEach(x=>x.classList.remove('highlight'));country.classList.add('highlight');const pop=atlasRuntime.node.querySelector('.atlas-popup');pop.innerHTML='<strong>'+escapeHTML(f.properties.name||'Country')+'</strong><p>'+lang('تم تحديد حدود الدولة على الخريطة.','Country outline highlighted on the map.')+'</p>';pop.classList.remove('hidden');return;}
});

document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.page){setPage(b.dataset.page);return}if(b.dataset.cat){setPage('category',b.dataset.cat);return}if(b.dataset.item){let [cat,idx]=b.dataset.item.split(':');setPage('detail',cat,+idx);return}if(b.dataset.layer){activeLayer=b.dataset.layer;document.querySelectorAll('[data-layer]').forEach(x=>x.classList.toggle('active',x===b));drawMarkers(activeLayer);return}if(b.dataset.game){gameStarted=true;selectedGameMode=b.dataset.game;quiz=createGame(selectedGameMode);state.quizIndex=0;state.quizScore=0;state.quizSelected=null;state.quizComplete=false;render();return}if(b.dataset.answer!==undefined&&state.quizSelected===null){state.quizSelected=+b.dataset.answer;if(state.quizSelected===quiz[state.quizIndex][4])state.quizScore++;render();return}if(b.id==='nextQuiz'){if(state.quizIndex===quiz.length-1){state.quizComplete=true;let p=saved();p.quizBest=Math.max(p.quizBest||0,state.quizScore);p['best_'+selectedGameMode]=Math.max(p['best_'+selectedGameMode]||0,state.quizScore);save(p)}else{state.quizIndex++;state.quizSelected=null}render();return}if(b.id==='restartQuiz'){state.quizIndex=0;state.quizScore=0;state.quizSelected=null;state.quizComplete=false;render();return}if(b.id==='toggleSeen'){let p=saved();p[`${state.category}_${state.item}`]=!p[`${state.category}_${state.item}`];p[state.category]=geo[state.category].filter((_,i)=>p[`${state.category}_${i}`]).length;save(p);render();return}if(b.id==='showMapPoint'){document.getElementById('detailMap')?.scrollIntoView({behavior:'smooth',block:'center'});return}if(b.id==='languageBtn'){state.lang=state.lang==='ar'?'en':'ar';localStorage.setItem('gv_lang',state.lang);render();return}if(b.id==='modeBtn'){state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('gv_theme',state.theme);render();return}if(b.id==='searchBtn'){openSearch();return}if(b.id==='closeSearch'){closeSearch();return}if(b.id==='menuBtn'||b.id==='menuTopics'){document.getElementById('sidebar').classList.toggle('open');return}if(b.id==='allCategories'){setPage('all');return}if(b.dataset.searchCat){closeSearch();setPage(b.dataset.searchItem!==undefined?'detail':'category',b.dataset.searchCat,b.dataset.searchItem!==undefined?+b.dataset.searchItem:null)}});
